import{z as n,x as i,o as r,c as d,q as A,j as s,D as t,d as e,s as o,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"浮点数的深入","description":"","frontmatter":{"title":"浮点数的深入","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sc-float-deep.md","filePath":"cs/sc-float-deep.md","lastUpdated":1791413859000}'),p={name:"cs/sc-float-deep.md"};function m(u,a,h,c,f,D){const l=i("Mermaid");return r(),d("div",null,[a[2]||(a[2]=A('<h1 id="浮点数的深入" tabindex="-1">浮点数的深入 <a class="header-anchor" href="#浮点数的深入" aria-label="Permalink to &quot;浮点数的深入&quot;">​</a></h1><div class="epigraph"><p>误差模型告诉你每步至多丢多少，精确性定理告诉你哪几步一步都不丢；只会前者的人，把所有账都算成运气。</p><footer>—— 据 Goldberg, ACM Computing Surveys, 1991；Higham, Accuracy and Stability of Numerical Algorithms 整理</footer></div><p><a href="/cs/ss-case-map">上一课</a>给「系统安全深化」收束：Dirty Pipe 对内核类别、Log4Shell 对供应链、CrowdStrike 对特权健壮性、Pegasus 对移动与硬件，四个公开案例对表归档——合法输入也能击穿特权层，安全是整条栈的性质。安全的类别表交了卷；数值主干到<a href="/cs/interpolation-runge">插值与龙格现象</a>收口时留过一句：不再碰 IEEE 位型本身。本课是「数值与科学计算」的第一课，偏偏回到位型。<a href="/cs/ieee-754">IEEE 754</a> 给过位布局，<a href="/cs/rounding-modes">舍入模式</a>给过四种朝向，<a href="/cs/denormal-nan">非规格化与 NaN</a> 给过边界编码；主干没有回答的是写算法的人每天要问的问题——<strong>哪些浮点运算给出的结果是精确的</strong>。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\mathrm{fl}\\) 模型是上界思维：每次运算至多引入 \\(|\\delta|\\le u\\) 的相对扰动。设计补偿算法、验证实现技巧、谈判跨平台复现时，需要的却是下界思维：哪几步<strong>一个舍入都不引入</strong>。分不清这两件事两头都错：把可以精确的事实也算进误差预算，算法显得比实际更不可救；把不精确的步骤当精确，又会在 \\(u\\) 量级上赌输。缺口因此是一份精确运算清单，外加它的两个推论——ulp 与相对误差的错位、用两个机器数拼一个更精的数。</p><h3 id="精确运算清单" tabindex="-1">精确运算清单 <a class="header-anchor" href="#精确运算清单" aria-label="Permalink to &quot;精确运算清单&quot;">​</a></h3><p>三条。其一，乘除 2 的幂精确：尾数不动、指数平移，除非撞上溢出或跌进非规格化。其二，Sterbenz 引理：若 \\(y/2\\le x\\le 2y\\)，则 \\(\\mathrm{fl}(x-y)\\) 逐位等于 \\(x-y\\)——近量相减这一步零舍入；<a href="/cs/catastrophic-cancellation">消去与灾难抵消</a>里危险的正是它的<strong>下游</strong>，不是这一步本身。其三，FMA：\\(\\mathrm{fl}(ab+c)\\) 只舍一次，全精度积在单元内部保留；<a href="/cs/fp-mul-fma">浮点乘法与 FMA</a> 给过指令，这里把它当「消灭一次中间舍入」的算法资源。</p><p><span class="marginnote">Sterbenz 的适用面比直觉宽：双精度里算 \\(1.0000001-1\\)，这一步零误差，误差全部来自 \\(1.0000001\\) 自己怎么来的。所以「减法丢精度」的说法不精确——丢精度的是把两个本不相等的量对消到近零之后还当真，对消那一步恰恰是精确的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>拿到清单，写算法的思路从「尽量少运算」变成「把舍入集中到无害的位置」。补偿求和是第一应用：<a href="/cs/summation-order">求和顺序</a>点过名的 Kahan 补偿要恢复每次加法丢掉的残差，靠的是 two-sum——加法虽不精确，却满足 \\(\\mathrm{fl}(a+b)=(a+b)-e\\)，且 \\(e\\) 本身可被精确算出，这是舍入到最近规则赠予的逆运算。第二应用是扩精度：Dekker 的 double-double 用一对双精度数表示约 106 位有效数字，运算归约到 two-sum 与两积之差的精确恢复，代价约二十次 flop，换来在 \\(\\kappa\\) 逼近 \\(1/u\\) 的问题上继续工作。</p>',10)),(r(),s(B,null,{default:t(()=>[o(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%E8%B4%A6%E6%9C%AC%EF%BC%9A%E6%AF%8F%E6%AD%A5%E4%B8%80%E4%B8%AA%20(1%2Bdelta)%22%5D%20--%3E%20LIST%5B%22%E7%B2%BE%E7%A1%AE%E5%9D%97%EF%BC%9A%E5%B9%82%E7%BC%A9%E6%94%BE%20%2F%20Sterbenz%20%2F%20FMA%22%5D%0A%20%20LIST%20--%3E%20COMP%5B%22%E8%A1%A5%E5%81%BF%E4%B8%8E%E6%89%A9%E7%B2%BE%E5%BA%A6%EF%BC%9Atwo-sum%E3%80%81double-double%22%5D%0A%20%20LIST%20--%3E%20BET%5B%22%E7%AE%97%E6%B3%95%E6%8A%BC%E6%B3%A8%EF%BC%9A%E8%88%8D%E5%85%A5%E9%9B%86%E4%B8%AD%E5%88%B0%E6%97%A0%E5%AE%B3%E6%AD%A5%22%5D%0A%20%20COMP%20--%3E%20BUD%5B%22%E8%AF%AF%E5%B7%AE%E9%A2%84%E7%AE%97%E5%8F%AA%E7%95%99%E7%BB%99%E5%89%A9%E4%BD%99%E6%AD%A5%E9%AA%A4%22%5D%0A%20%20BET%20--%3E%20BUD%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("这些精确性为什么成立，答案全在位型里。近量相减：对阶之后两数指数相等，差是同尺度的小数，天然落在网格上，不需要舍入。FMA：中间积以无限精度留在单元里，只有出口舍一次。two-sum：舍入误差 \\(e\\) 本身是两个机器数之差，可以再用同样的加法结构恢复。三者的共同点是："),E("strong",null,"精确性是位布局与舍入规则的推论，不是硬件的额外承诺"),e("——所以编译器打开收缩与重结合（"),E("a",{href:"/cs/fast-math"},"fast-math"),e("）时，FMA 合同与求和顺序会被改写，补偿算法当场失效。精确块是写给编译器的合同，不是写给自己看的注释。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"two-sum 可以想象成「加法自带的悔棋键」：\\(\\mathrm{fl}(a+b)\\) 把真实和砍掉一点尾巴，而被砍掉的部分 \\(e\\) 恰好还能用一个机器数装下，再加一次就能捡回来。数字实例：算 \\(1+2^{-53}\\)，舍入到最近得 \\(1\\)，丢掉的 \\(e=2^{-53}\\) 本身就在双精度网格上——Kahan 求和每步捡的就是这个残差。")],-1)),(r(),s(B,null,{default:t(()=>[o(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%BF%99%E6%AC%A1%E5%87%8F%E6%B3%95%20x%E2%88%92y%20%E4%BC%9A%E5%BC%95%E5%85%A5%E8%88%8D%E5%85%A5%E5%90%97%3F%22%5D%20--%3E%20C%7B%22y%2F2%20%E2%89%A4%20x%20%E2%89%A4%202y%20%3F%22%7D%0A%20%20C%20--%3E%7C%22%E6%98%AF%EF%BC%9A%E4%B8%A4%E6%95%B0%E5%90%8C%20binade%20%E7%9B%B8%E9%82%BB%E6%AE%B5%22%7C%20EX%5B%22%E5%AF%B9%E9%98%B6%E5%90%8E%E6%8C%87%E6%95%B0%E7%9B%B8%E7%AD%89%3Cbr%2F%3E%E5%B7%AE%E5%A4%A9%E7%84%B6%E8%90%BD%E5%9C%A8%E7%BD%91%E6%A0%BC%E4%B8%8A%22%5D%0A%20%20EX%20--%3E%20EXACT%5B%22%E9%9B%B6%E8%88%8D%E5%85%A5%EF%BC%9A%E7%BB%93%E6%9E%9C%E9%80%90%E4%BD%8D%E7%B2%BE%E7%A1%AE%22%5D%0A%20%20C%20--%3E%7C%22%E5%90%A6%22%7C%20SH%5B%22%E5%AF%B9%E9%98%B6%E7%A7%BB%E4%BD%8D%E4%B8%A2%E6%8E%89%E4%BD%8E%E4%BD%8D%E5%B0%BE%E6%95%B0%22%5D%0A%20%20SH%20--%3E%20RD%5B%22%E8%88%8D%E4%B8%80%E6%AC%A1%EF%BC%9A%7C%CE%B4%7C%20%E2%89%A4%20u%22%5D%0A%20%20EXACT%20--%3E%20USE%5B%22%E5%8F%AF%E5%BD%93%E7%AE%97%E6%B3%95%E8%B5%84%E6%BA%90%EF%BC%9A%E5%B7%AE%E5%88%86%E3%80%81%E6%AE%8B%E5%B7%AE%E6%8F%90%E5%8F%96%22%5D%0A%20%20RD%20--%3E%20BUD%5B%22%E8%AE%A1%E5%85%A5%E8%AF%AF%E5%B7%AE%E9%A2%84%E7%AE%97%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">ulp 是相邻两个浮点数的最小间距。双精度在 \\(1.0\\) 附近 \\(\\mathrm{ulp}\\approx 2.2\\times 10^{-16}\\)；同一个 binade 走向 \\(2.0\\) 时间距不变，但数变大了，同样半个 ulp 的舍入摊到更大的数上，相对误差就翻倍——这就是「下缘比上缘准一倍」。所以比较两个库谁更准，先问它报的口径是 ulp 还是相对误差。</span></p><p>ulp 语言补最后一块：相对误差随二进指数逐 binade 摆动，同一格式在下缘比上缘「更准」一倍；比较两种实现的精度声明时先问口径是 ulp 还是相对误差，否则 \\(2^{-53}\\) 对 \\(2^{-54}\\) 的争吵没有裁判。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重画位域、不重列异常旗标，那些在<a href="/cs/denormal-nan">非规格化与 NaN</a> 与<a href="/cs/fp-exceptions">浮点异常与标志</a>；十进制 754 与正确舍入的超越函数库也不展开——后者是库的合同，不是标准强制的。double-double 不是任意精度：仍是浮点，仍会溢出，只是把 \\(u\\) 推小约半量级。<span class="marginnote">初学者容易把 double-double 当成任意精度库的平替，实际上它只是把 \\(u\\) 从 \\(2^{-53}\\) 推到约 \\(2^{-104}\\)：仍是浮点、仍会溢出、仍受舍入规则约束。可以把它想象成「两支笔接力写同一个数」——高位一支、残差一支，而不是一张想写多长写多长的纸。</span>后课默认：近量差精确、FMA 消一次舍入、two-sum 可行，并把它们当算法资源使用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>精确块：2 的幂缩放、Sterbenz 近量差、FMA 单次舍入，都是位型与舍入规则的推论。</li><li>补偿求和与 double-double 靠 two-sum 的可逆性，把误差集中、把 \\(u\\) 推小。</li><li>fast-math 式的重结合与收缩会破坏精确块合同，补偿算法随之失效。</li><li>精度声明先分清 ulp 与相对误差口径。</li><li>出处：Goldberg, ACM Computing Surveys, 1991；Higham；Dekker, Numerische Mathematik, 1971；IEEE 754-2008。</li></ul>',6))])}const F=n(p,[["render",m]]);export{b as __pageData,F as default};
